lib='''"""Shared ARC helpers."""
from collections import Counter

def background(g):
    """Most common cell value in a grid."""
    return Counter(v for row in g for v in row).most_common(1)[0][0]

def row_bands(g, bg=None):
    """Contiguous groups of row indices containing non-background cells."""
    if bg is None: bg = background(g)
    nz = [r for r in range(len(g)) if any(v != bg for v in g[r])]
    grps = []
    for r in nz:
        if grps and r == grps[-1][-1] + 1: grps[-1].append(r)
        else: grps.append([r])
    return grps

def shifted_ghost(g, marker=1, bg=None):
    """For two copies of a pattern band, mark the second copy's erased cells
    (cells that should be the first copy shifted right by 1) with `marker`."""
    if bg is None: bg = background(g)
    grps = row_bands(g, bg)
    if len(grps) != 2: return [row[:] for row in g]
    top, bot = grps
    g = [row[:] for row in g]
    T = [g[r] for r in top]; B = [g[r] for r in bot]
    def resid(src, ers):
        return sum(1 for a, b in zip(src, ers) for c in range(1, len(b))
                   if (b[c] == bg and a[c-1] != bg) or (b[c] != bg and b[c] != a[c-1]))
    src, ers = (T, B) if resid(T, B) <= resid(B, T) else (B, T)
    for a, b in zip(src, ers):
        for c in range(1, len(b)):
            if b[c] == bg and a[c-1] != bg: b[c] = marker
    return g
